(() => {
  const finePointer = window.matchMedia('(pointer: fine) and (prefers-reduced-motion: no-preference)');
  if (!finePointer.matches) return;
  const cursor = document.createElement('span');
  cursor.className = 'cloud-cursor is-hidden';
  cursor.setAttribute('aria-hidden', 'true');
  document.body.append(cursor);
  document.documentElement.classList.add('cloud-cursor-active');
  let lastPuff = 0;
  let puffCount = 0;
  document.addEventListener('pointermove', event => {
    if (event.pointerType !== 'mouse' && event.pointerType !== 'pen') return;
    cursor.style.left = `${event.clientX}px`;
    cursor.style.top = `${event.clientY}px`;
    cursor.classList.remove('is-hidden');
    cursor.classList.toggle('is-interactive', Boolean(event.target instanceof Element && event.target.closest('a, button, input, select, textarea, [role="button"]')));
    const now = performance.now();
    if (now - lastPuff < 48 || puffCount >= 18) return;
    lastPuff = now;
    puffCount++;
    const puff = document.createElement('span');
    puff.className = 'cloud-puff';
    puff.setAttribute('aria-hidden', 'true');
    puff.style.left = `${event.clientX + (Math.random() - .5) * 16}px`;
    puff.style.top = `${event.clientY + (Math.random() - .5) * 12}px`;
    puff.style.setProperty('--dx', `${-12 + (Math.random() - .5) * 28}px`);
    puff.style.setProperty('--dy', `${14 + Math.random() * 24}px`);
    puff.style.setProperty('--size', `${7 + Math.random() * 8}px`);
    puff.addEventListener('animationend', () => { puff.remove(); puffCount--; }, { once: true });
    document.body.append(puff);
  }, { passive: true });
  document.addEventListener('pointerout', event => { if (!event.relatedTarget) cursor.classList.add('is-hidden'); });
  document.addEventListener('pointerdown', () => cursor.classList.add('is-pressed'));
  document.addEventListener('pointerup', () => cursor.classList.remove('is-pressed'));
  window.addEventListener('blur', () => cursor.classList.add('is-hidden'));
})();